/* A client-facing narrative around the working product collection. */
let storyFeatured=0;
const clientValue=[
['Win the next opportunity','Scattered requirements. A blank proposal. A deadline approaching.','One conversation becomes a structured proposal your team can refine and review.','Turn the brief into a response',['RFP requirements','Drafted sections','Review & approval']],
['Keep the conversation going','A successful webinar ends with a generic follow-up—or no follow-up at all.','Use what attendees watched and asked to prepare relevant emails and three follow-ups.','Make every follow-up relevant',['Webinar context','Personalized email','Three follow-ups']],
['Focus sales on the right leads','Signals live in different systems and sellers lack a shared way to prioritize.','See account context, understand priority, and give every promising lead a clear next step.','Know who deserves attention',['Connected signals','Priority reasoning','Assigned next steps']],
['Test before you commit','An idea looks good internally, but objections and blind spots remain unexplored.','Compare simulated persona reactions and refine the concept before testing it with real people.','Pressure-test the message',['Audience personas','Simulated feedback','Refined concept']],
['Plan with a shared set of numbers','Department requests arrive in separate spreadsheets with inconsistent assumptions.','Build and compare department budgets in a shared workspace, with explanations behind the numbers.','Connect goals to a workable budget',['Department goals','Budget assumptions','Company-wide plan']],
['See what is driving revenue','Leadership has plenty of sales data but no clear connection between pipeline and performance.','Move from the revenue headline to the accounts, stages, and trends behind it.','Turn sales data into decisions',['Historical results','Current pipeline','Revenue outlook']],
['Put capacity where it matters','Project commitments and team availability are difficult to reconcile.','Spot overload, inspect staffing risks, and test assignments before changing the delivery plan.','Balance the work and the team',['Project demand','Team capacity','Assignment options']],
['Keep everyone aligned','Client updates, files, decisions, and contractor work are spread across too many places.','Give each participant a shared project context and a view that fits their role.','Bring the project into one workspace',['Project context','Connected files','Role-specific views']],
['Find the meaning in the reports','Reports are available, but finding the right answer still means searching and comparing files.','Explore visual summaries, trace the source, and ask questions across your reporting.','Get from reports to understanding',['Report collection','Visual analysis','Source-backed context']],
['Make the future easier to discuss','A forecast arrives as a final number with assumptions hidden underneath.','Change business drivers, compare scenarios, and explain the outlook in the same workspace.','See what changes the forecast',['Baseline performance','Adjustable drivers','Scenario comparison']],
['Build a defensible business case','A promising project has benefits, but its full cost and payback are hard to evaluate.','Model benefits and costs, test the assumptions, and understand what the investment needs to deliver.','Evaluate the build before investing',['Investment inputs','ROI & payback','Sensitivity analysis']],
['Give clients delivery clarity','Progress updates do not always make milestones, blockers, and decisions easy to understand.','See the portfolio, open each initiative, and connect the status to its next decision.','Make every project easier to follow',['Portfolio health','Milestone detail','Decisions & risks']],
['Start the day with useful prospects','Researching accounts and writing the first message consumes time before outreach even begins.','Review researched accounts and compare three email and LinkedIn content angles in one queue.','Move from research to ready-to-review',['Research brief','Qualified accounts','Three content angles']],
['Protect the client relationship','Warning signs appear in separate conversations, reports, and renewal records.','Bring the signals together, explain account health, and assign the next relationship action.','See the risk. Know the next step.',['Account signals','Explainable health','Owned action plans']]
];
function storySelect(i){storyFeatured=i;render()}
function storyJump(){document.getElementById('studioLibrary').scrollIntoView({behavior:'smooth',block:'start'})}
function storyPreview(i){if(i===13)return `<div class="story-health-preview"><span>CLIENT PORTFOLIO</span><div class="story-preview-metric">${Math.round(healthAccounts.reduce((sum,a)=>sum+healthScore(a),0)/healthAccounts.length)}<small>/ 100 health</small></div>${[['Harbor Financial',90],['Cedar Health Partners',64],['Northstar Manufacturing',56]].map(([n,v])=>`<div class="story-preview-row"><b>${n}</b><span><i style="width:${v}%"></i></span><em>${v}</em></div>`).join('')}</div>`;return studioPreview(i)}
studioHome=function(){const ids=studioView==='All'?toolsList.map((_,i)=>i):studioGroups[studioView],v=clientValue[storyFeatured];return `<div class="client-collection"><section class="client-hero"><div class="client-hero-copy"><div class="client-eyebrow">NINE-67 / APPLICATION SHOWCASE</div><h1>Your everyday work.<br><span>A better way to do it.</span></h1><p>Explore the applications we build around real business workflows. See how your team could research, plan, collaborate, and make decisions with AI built into the work.</p><div class="client-hero-actions"><button class="client-primary" onclick="storyJump()">Explore the applications ${icon('arrow')}</button><button class="client-secondary" onclick="scopeApplication(-1)">Map your workflow</button></div><div class="client-hero-proof"><b>14 working demos</b><span>Built by Nine-67</span><span>Tailored to your business</span></div></div><div class="client-feature"><div class="client-feature-tabs">${[[0,'Create'],[5,'Analyze'],[7,'Collaborate'],[13,'Retain']].map(([i,l])=>`<button class="${storyFeatured===i?'active':''}" onclick="storySelect(${i})">${l}</button>`).join('')}</div><div class="client-feature-content"><div class="client-feature-label">${icon(productIcons[storyFeatured])}<span>${toolsList[storyFeatured][0]}</span><small>INTERACTIVE DEMO</small></div><h2>${v[3]}</h2><div class="client-feature-preview">${storyPreview(storyFeatured)}</div><div class="client-feature-steps">${v[4].map((s,i)=>`<span><small>0${i+1}</small>${s}</span>`).join('')}</div><button class="client-feature-open" onclick="nav(${storyFeatured})">Try ${toolsList[storyFeatured][0]} ${icon('arrow')}</button></div></div></section><section class="client-outcomes"><div><span class="client-eyebrow">START WITH THE WORK</span><h2>What would you like to improve?</h2></div>${[['Growth','Win and develop business','Research, qualification, proposals, and follow-up.'],['Delivery','Deliver with clarity','Projects, people, client relationships, and collaboration.'],['Planning','Make informed decisions','Budgets, reporting, forecasts, and investment cases.']].map(([g,h,p],i)=>`<button onclick="studioView='${g}';render();storyJump()"><span>0${i+1}</span><div><h3>${h}</h3><p>${p}</p></div>${icon('arrow')}</button>`).join('')}</section><section id="studioLibrary" class="client-library"><div class="client-library-heading"><div><span class="client-eyebrow">THE APPLICATIONS</span><h2>See the work. Try the workflow.</h2><p>Each application demonstrates a different way we can help your business.</p></div><div class="studio-filter">${['All','Growth','Delivery','Planning'].map(g=>`<button class="${studioView===g?'active':''}" onclick="studioView='${g}';render();storyJump()">${g==='All'?'All applications':g}<span>${g==='All'?toolsList.length:studioGroups[g].length}</span></button>`).join('')}</div></div><div class="client-application-grid">${ids.map(i=>{let c=clientValue[i];return `<article class="client-application" data-application="${i}"><div class="client-application-top">${icon(productIcons[i])}<span>${productStories[i].audience}</span><small>${String(i+1).padStart(2,'0')}</small></div><h3>${toolsList[i][0]}</h3><h4>${c[0]}</h4><div class="client-card-preview" aria-hidden="true">${storyPreview(i)}</div><div class="client-before-after"><div><span>THE CHALLENGE</span><p>${c[1]}</p></div><div><span>WHAT WE BUILT</span><p>${c[2]}</p></div></div><div class="client-card-actions"><button onclick="nav(${i})">Explore the application ${icon('arrow')}</button><button aria-label="Adapt ${toolsList[i][0]} to your business" onclick="scopeApplication(${i})">For your team</button></div></article>`}).join('')}</div></section><section class="client-adapt"><div><span class="client-eyebrow">FROM EXAMPLE TO YOUR APPLICATION</span><h2>Built around your process.<br>Connected to your environment.</h2><p>The starting point is your team’s work: the steps that take time, the information that gets lost, and the decisions that could be clearer.</p><button class="client-primary" onclick="scopeApplication(-1)">Outline your use case ${icon('arrow')}</button></div><div class="client-adapt-steps">${[['Understand the work','Identify the users, handoffs, source information, and outcome that matter.'],['Shape the application','Choose the workflow, review points, and integrations that fit your team.'],['Make it useful in practice','Build, test, and refine around real tasks and how people actually use the tool.']].map(([h,p],i)=>`<div><span>0${i+1}</span><section><h3>${h}</h3><p>${p}</p></section></div>`).join('')}</div></section><div class="client-toolkit"><span>OUR DEVELOPMENT TOOLKIT</span><p>Claude API <i>·</i> OpenAI API <i>·</i> Microsoft Teams <i>·</i> SharePoint <i>·</i> Azure <i>·</i> Supabase <i>·</i> Vercel</p></div><p class="studio-disclosure">Representative interactive demos · Sample data · Simulated AI · Integrations tailored per project</p></div>`};
const clientOriginalIntro=studioProductIntro;
studioProductIntro=function(){return clientOriginalIntro()};

function scopeApplication(i){const saved=JSON.parse(localStorage.getItem('nine67-client-brief')||'null')||{};draw(i<0?'What would you like to improve?':toolsList[i][0]+' for your team',`<p class="client-scope-intro">Outline the workflow you want to improve. Create a short discussion brief to share with Nine-67.</p>${i>=0?`<div class="client-scope-example"><span>STARTING POINT</span><h3>${clientValue[i][0]}</h3><p>${clientValue[i][2]}</p></div>`:''}<label class="client-scope-field">Your team or department<input id="scopeTeam" placeholder="e.g. Sales operations" value="${esc(saved.team||'')}"></label><label class="client-scope-field">What happens today?<textarea id="scopeProblem" placeholder="Describe the task, the handoffs, and where time gets lost…">${esc(saved.problem||'')}</textarea></label><label class="client-scope-field">What would a better outcome look like?<textarea id="scopeOutcome" placeholder="e.g. Every qualified lead gets a relevant response within one day…">${esc(saved.outcome||'')}</textarea></label><label class="client-scope-field">Which systems do you use?<input id="scopeSystems" placeholder="e.g. Teams, SharePoint, CRM, spreadsheets" value="${esc(saved.systems||'')}"></label><div class="health-buttons">${ib('Create discussion brief',`scopeBuild(${i})`,'file','primary')}</div><p class="exp-note">Saved only in this browser. Nothing is submitted or sent.</p>`)}
function scopeBuild(i){const b={app:i<0?'Custom application':toolsList[i][0],team:$('#scopeTeam').value.trim(),problem:$('#scopeProblem').value.trim(),outcome:$('#scopeOutcome').value.trim(),systems:$('#scopeSystems').value.trim()};if(!b.problem||!b.outcome){toast('Add the current workflow and your desired outcome');return}localStorage.setItem('nine67-client-brief',JSON.stringify(b));scopeShow()}
function scopeShow(){const b=JSON.parse(localStorage.getItem('nine67-client-brief'));draw('Your application discussion brief',`<div class="client-brief-title"><span>NINE-67 / WORKFLOW DISCOVERY</span><h2>${esc(b.app)}</h2></div>${[['Team',b.team||'To discuss'],['Current workflow',b.problem],['Desired outcome',b.outcome],['Systems',b.systems||'To discuss']].map(([h,p])=>`<section class="client-brief-section"><h3>${h}</h3><p>${esc(p)}</p></section>`).join('')}<section class="client-brief-section"><h3>Questions to resolve together</h3><p>Who uses the workflow? What information can the application access? Which steps need human approval? How will we measure whether it helps?</p></section>${ib('Download brief','scopeDownload()','download','primary')}<p class="exp-note">This is a discussion brief, not a proposal or delivery commitment. No information has been sent.</p>`)}
function scopeDownload(){const b=JSON.parse(localStorage.getItem('nine67-client-brief'));download('Nine-67-workflow-brief.txt','NINE-67 / WORKFLOW DISCUSSION\n\nApplication: '+b.app+'\nTeam: '+b.team+'\n\nCurrent workflow\n'+b.problem+'\n\nDesired outcome\n'+b.outcome+'\n\nSystems\n'+b.systems+'\n\nQuestions to discuss\nUsers, data access, human approvals, and success measures.');toast('Discussion brief downloaded')}
render();
